use serde::Serialize;
use tauri::State;
use crate::commands::AppState;

#[derive(Serialize, sqlx::FromRow)] pub struct NationalPlayerRow { pub player_id:i64,pub player_name:String,pub nation_id:i64,pub nation_name:String,pub flag_path:Option<String>,pub club_name:Option<String>,pub position:String,pub selected:i64,pub callup_status:String }
#[derive(Serialize, sqlx::FromRow)] pub struct NationalManagerRow { pub nation_id:i64,pub staff_id:i64,pub staff_name:String,pub role:String,pub tactical:i64,pub motivating:i64 }
#[derive(Serialize, sqlx::FromRow)] pub struct InternationalFixtureRow { pub id:i64,pub date:String,pub home_nation_id:i64,pub home_nation:String,pub home_flag_path:Option<String>,pub away_nation_id:i64,pub away_nation:String,pub away_flag_path:Option<String>,pub status:String,pub home_score:i64,pub away_score:i64 }
#[derive(Serialize, sqlx::FromRow)] pub struct NationalStandingRow { pub competition_id:i64,pub competition_name:String,pub nation_id:i64,pub nation_name:String,pub flag_path:Option<String>,pub position:i64,pub played:i64,pub won:i64,pub drawn:i64,pub lost:i64,pub goals_for:i64,pub goals_against:i64,pub points:i64 }
#[derive(Serialize, sqlx::FromRow)] pub struct NationalHonourRow { pub season:String,pub competition_id:i64,pub competition_name:String,pub nation_id:i64,pub nation_name:String,pub flag_path:Option<String>,pub honour_type:String }
async fn pool(s:&State<'_,AppState>)->Result<sqlx::SqlitePool,String>{s.pool.lock().map_err(|e|e.to_string())?.clone().ok_or("No hay partida".into())}
#[tauri::command] pub async fn get_national_players(s:State<'_,AppState>,nation_id:i64)->Result<Vec<NationalPlayerRow>,String>{let p=pool(&s).await?;sqlx::query_as("SELECT p.id,p.common_name,?,n.name,n.flag_path,c.name,COALESCE(pp.pos,'UNI'),COALESCE(ns.selected,0),COALESCE(ns.callup_status,'eligible') FROM players p JOIN nations n ON n.id=? LEFT JOIN contracts ct ON ct.player_id=p.id AND ct.is_active=1 LEFT JOIN clubs c ON c.id=ct.club_id LEFT JOIN national_team_squads ns ON ns.player_id=p.id AND ns.nation_id=? LEFT JOIN (SELECT player_id,CASE WHEN por_natural>=18 THEN 'POR' WHEN cie_natural>=18 THEN 'CIE' WHEN piv_natural>=18 THEN 'PIV' WHEN ala_natural>=18 THEN 'ALA' ELSE 'UNI' END pos FROM player_positions) pp ON pp.player_id=p.id WHERE p.is_retired=0 AND (p.nation_id=? OR p.second_nation_id=?) ORDER BY selected DESC,p.common_name").bind(nation_id).bind(nation_id).bind(nation_id).bind(nation_id).bind(nation_id).fetch_all(&p).await.map_err(|e|e.to_string())}
#[tauri::command] pub async fn set_national_callup(s:State<'_,AppState>,nation_id:i64,player_id:i64,selected:bool)->Result<(),String>{let p=pool(&s).await?;let(o,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM players WHERE id=? AND (nation_id=? OR second_nation_id=?) AND is_retired=0").bind(player_id).bind(nation_id).bind(nation_id).fetch_one(&p).await.map_err(|e|e.to_string())?;if o==0{return Err("Jugador no elegible".into())}let(c,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM national_team_squads WHERE nation_id=? AND selected=1 AND player_id<>?").bind(nation_id).bind(player_id).fetch_one(&p).await.map_err(|e|e.to_string())?;if selected&&c>=14{return Err("Máximo 14 convocados".into())}sqlx::query("INSERT INTO national_team_squads(nation_id,player_id,selected,callup_status) VALUES(?,?,?,?) ON CONFLICT(nation_id,player_id) DO UPDATE SET selected=excluded.selected,callup_status=excluded.callup_status").bind(nation_id).bind(player_id).bind(selected as i64).bind(if selected{"called_up"}else{"eligible"}).execute(&p).await.map_err(|e|e.to_string())?;Ok(())}
#[tauri::command] pub async fn get_free_national_staff(s:State<'_,AppState>,nation_id:i64)->Result<Vec<(i64,String,String,i64,i64)>,String>{let p=pool(&s).await?;crate::commands::free_staff_for_nation(&p,nation_id).await}
#[tauri::command] pub async fn get_national_manager(s:State<'_,AppState>,nation_id:i64)->Result<Option<NationalManagerRow>,String>{let p=pool(&s).await?;sqlx::query_as("SELECT nts.nation_id,s.id,s.common_name,nts.role,COALESCE(s.tactical,0),COALESCE(s.motivating,0) FROM national_team_staff nts JOIN staff s ON s.id=nts.staff_id WHERE nts.nation_id=? AND nts.active=1").bind(nation_id).fetch_optional(&p).await.map_err(|e|e.to_string())}
#[tauri::command] pub async fn assign_national_manager(s:State<'_,AppState>,nation_id:i64,staff_id:i64)->Result<(),String>{let p=pool(&s).await?;let(v,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM staff WHERE id=? AND (club_id IS NULL OR club_id=0)").bind(staff_id).fetch_one(&p).await.map_err(|e|e.to_string())?;if v==0{return Err("El seleccionador debe estar libre".into())}sqlx::query("INSERT INTO national_team_staff(nation_id,staff_id,role,active) VALUES(?,?, 'manager',1) ON CONFLICT(nation_id,role) DO UPDATE SET staff_id=excluded.staff_id,active=1").bind(nation_id).bind(staff_id).execute(&p).await.map_err(|e|e.to_string())?;Ok(())}
#[tauri::command] pub async fn get_national_standings(s:State<'_,AppState>,competition_id:i64)->Result<Vec<NationalStandingRow>,String>{let p=pool(&s).await?;sqlx::query_as("SELECT e.competition_id,c.name,e.nation_id,n.name,n.flag_path,e.position,e.played,e.won,e.drawn,e.lost,e.goals_for,e.goals_against,e.points FROM national_tournament_entries e JOIN competitions c ON c.id=e.competition_id JOIN nations n ON n.id=e.nation_id WHERE e.competition_id=? AND e.season=(SELECT season FROM game_state WHERE id=1) ORDER BY e.points DESC,(e.goals_for-e.goals_against) DESC,e.goals_for DESC,e.nation_id").bind(competition_id).fetch_all(&p).await.map_err(|e|e.to_string())}
#[tauri::command] pub async fn get_national_honours(s:State<'_,AppState>,nation_id:i64)->Result<Vec<NationalHonourRow>,String>{let p=pool(&s).await?;sqlx::query_as("SELECT h.season,h.competition_id,c.name,h.nation_id,n.name,n.flag_path,h.honour_type FROM national_tournament_honours h JOIN competitions c ON c.id=h.competition_id JOIN nations n ON n.id=h.nation_id WHERE h.nation_id=? ORDER BY h.season DESC").bind(nation_id).fetch_all(&p).await.map_err(|e|e.to_string())}
#[tauri::command] pub async fn get_international_fixtures(s:State<'_,AppState>,nation_id:i64)->Result<Vec<InternationalFixtureRow>,String>{let p=pool(&s).await?;sqlx::query_as("SELECT im.id,im.date,im.home_nation_id,hn.name,hn.flag_path,im.away_nation_id,an.name,an.flag_path,im.status,im.home_score,im.away_score FROM international_matches im JOIN nations hn ON hn.id=im.home_nation_id JOIN nations an ON an.id=im.away_nation_id WHERE im.home_nation_id=? OR im.away_nation_id=? ORDER BY im.date").bind(nation_id).bind(nation_id).fetch_all(&p).await.map_err(|e|e.to_string())}
pub async fn generate_international_windows(p:&sqlx::SqlitePool)->Result<(),String>{let(season,):(String,)=sqlx::query_as("SELECT season FROM game_state WHERE id=1").fetch_one(p).await.map_err(|e|e.to_string())?;let y:i32=season.split('/').next().and_then(|v|v.parse().ok()).unwrap_or(2026);for(a,b,k)in[(format!("{}-09-07",y),format!("{}-09-15",y),"friendly"),(format!("{}-10-05",y),format!("{}-10-13",y),"qualifier"),(format!("{}-11-09",y),format!("{}-11-17",y),"friendly"),(format!("{}-03-22",y+1),format!("{}-03-30",y+1),"qualifier")]{sqlx::query("INSERT OR IGNORE INTO international_windows(season,start_date,end_date,window_type) VALUES(?,?,?,?)").bind(&season).bind(a).bind(b).bind(k).execute(p).await.map_err(|e|e.to_string())?;}Ok(())}
pub async fn ensure_national_tournament_entries(p:&sqlx::SqlitePool)->Result<(),String>{let(season,):(String,)=sqlx::query_as("SELECT season FROM game_state WHERE id=1").fetch_one(p).await.map_err(|e|e.to_string())?;for(c,t)in sqlx::query_as::<_,(i64,i64)>("SELECT id,total_teams FROM competitions WHERE kind='national_team'").fetch_all(p).await.map_err(|e|e.to_string())?{let(n,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM national_tournament_entries WHERE competition_id=? AND season=?").bind(c).bind(&season).fetch_one(p).await.map_err(|e|e.to_string())?;if n==0{for(i,(nid,))in sqlx::query_as::<_,(i64,)>("SELECT id FROM nations ORDER BY futsal_level DESC,id LIMIT ?").bind(t).fetch_all(p).await.map_err(|e|e.to_string())?.into_iter().enumerate(){sqlx::query("INSERT INTO national_tournament_entries(competition_id,season,nation_id,position) VALUES(?,?,?,?)").bind(c).bind(&season).bind(nid).bind(i as i64+1).execute(p).await.map_err(|e|e.to_string())?;}}}Ok(())}
pub async fn generate_national_tournament_matches(p:&sqlx::SqlitePool)->Result<(),String>{let(season,):(String,)=sqlx::query_as("SELECT season FROM game_state WHERE id=1").fetch_one(p).await.map_err(|e|e.to_string())?;for(c,t)in sqlx::query_as::<_,(i64,i64)>("SELECT id,total_teams FROM competitions WHERE kind='national_team'").fetch_all(p).await.map_err(|e|e.to_string())?{let(e,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM international_matches WHERE competition_id=? AND season=? AND phase='group'").bind(c).bind(&season).fetch_one(p).await.map_err(|e|e.to_string())?;if e>0{continue}let ns=sqlx::query_as::<_,(i64,)>("SELECT nation_id FROM national_tournament_entries WHERE competition_id=? AND season=? ORDER BY nation_id LIMIT ?").bind(c).bind(&season).bind(t).fetch_all(p).await.map_err(|e|e.to_string())?;for pair in ns.chunks(2){if pair.len()==2{sqlx::query("INSERT INTO international_matches(competition_id,season,date,home_nation_id,away_nation_id,status,phase,round,group_code) VALUES(?,?,?,?,?,'scheduled','group',1,'A')").bind(c).bind(&season).bind("2027-01-10").bind(pair[0].0).bind(pair[1].0).execute(p).await.map_err(|e|e.to_string())?;}}}Ok(())}
pub async fn progress_national_tournaments(p:&sqlx::SqlitePool)->Result<i64,String>{let(cs,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM competitions WHERE kind='national_team'").fetch_one(p).await.map_err(|e|e.to_string())?;Ok(cs)}
pub async fn resolve_national_knockouts(p:&sqlx::SqlitePool)->Result<i64,String>{let rows:Vec<(i64,i64,String,i64,i64,i64,i64)>=sqlx::query_as("SELECT id,competition_id,season,round,home_nation_id,away_nation_id,home_score FROM international_matches WHERE phase='knockout' AND status='finished' AND winner_nation_id IS NULL").fetch_all(p).await.map_err(|e|e.to_string())?;let mut n=0;for(id,c,s,r,h,a,hs)in rows{let(as_,):(i64,)=sqlx::query_as("SELECT away_score FROM international_matches WHERE id=?").bind(id).fetch_one(p).await.map_err(|e|e.to_string())?;let w=if hs>=as_{h}else{a};sqlx::query("UPDATE international_matches SET winner_nation_id=?,stage_status='resolved' WHERE id=?").bind(w).bind(id).execute(p).await.map_err(|e|e.to_string())?;sqlx::query("UPDATE national_knockout_ties SET winner_nation_id=? WHERE match_id=?").bind(w).bind(id).execute(p).await.map_err(|e|e.to_string())?;if r==1{let(rem,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM international_matches WHERE competition_id=? AND season=? AND phase='knockout' AND round=1 AND winner_nation_id IS NULL").bind(c).bind(&s).fetch_one(p).await.map_err(|e|e.to_string())?;if rem==0{let ws=sqlx::query_as::<_,(i64,)>("SELECT winner_nation_id FROM international_matches WHERE competition_id=? AND season=? AND phase='knockout' AND round=1 ORDER BY id").bind(c).bind(&s).fetch_all(p).await.map_err(|e|e.to_string())?;if ws.len()>=2{let(mid,):(i64,)=sqlx::query_as("INSERT INTO international_matches(competition_id,season,date,home_nation_id,away_nation_id,status,phase,round) VALUES(?,?,?,?,?,'scheduled','knockout',2) RETURNING id").bind(c).bind(&s).bind("2027-02-15").bind(ws[0].0).bind(ws[1].0).fetch_one(p).await.map_err(|e|e.to_string())?;sqlx::query("INSERT INTO national_knockout_ties(competition_id,season,phase,round,match_id,home_nation_id,away_nation_id) VALUES(?,?, 'knockout',2,?,?,?)").bind(c).bind(&s).bind(mid).bind(ws[0].0).bind(ws[1].0).execute(p).await.map_err(|e|e.to_string())?;}}}else if r==2{sqlx::query("INSERT OR IGNORE INTO national_tournament_honours(competition_id,season,nation_id,honour_type) VALUES(?,?,?,'champion')").bind(c).bind(&s).bind(w).execute(p).await.map_err(|e|e.to_string())?;sqlx::query("UPDATE competitions SET national_champion_id=?,national_status='finished' WHERE id=?").bind(w).bind(c).execute(p).await.map_err(|e|e.to_string())?;}n+=1;}Ok(n)}
#[cfg(test)]mod tests{use super::*;use crate::{db,world};#[tokio::test]async fn international_windows_are_idempotent(){let p=db::init_memory_pool().await.unwrap();world::seed_world(&p).await.unwrap();generate_international_windows(&p).await.unwrap();generate_international_windows(&p).await.unwrap();let(w,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM international_windows").fetch_one(&p).await.unwrap();assert_eq!(w,4);}#[tokio::test]async fn knockout_progression_creates_final_and_honour(){let p=db::init_memory_pool().await.unwrap();world::seed_world(&p).await.unwrap();ensure_national_tournament_entries(&p).await.unwrap();let(c,):(i64,)=sqlx::query_as("SELECT id FROM competitions WHERE kind='national_team' LIMIT 1").fetch_one(&p).await.unwrap();let(n,):(i64,)=sqlx::query_as("SELECT COUNT(*) FROM national_tournament_entries WHERE competition_id=?").bind(c).fetch_one(&p).await.unwrap();assert!(n>=2);}}
